import {initFinance,financeDay,financeAction} from './finance.js?v=3.7.0';
import {initContext,newPerson,observeLife,contextEvent,delegateChoice,rememberChoice} from './life-context.js?v=3.7.0';
import {canChange} from './commands.js?v=3.7.0';
import {hero,log,clamp,rng,team} from './engine.js?v=3.7.0';
export function initLife(s){s.life??={fame:5,morale:70,partner:null,children:[],family:70,delegated:false,agent:'Équilibré',lifestyle:'simple',investments:0,property:null,sponsors:[],nextEvent:s.day+35,ledger:[],history:[]};s.relationships??={coach:55,team:55,agent:50,mentor:50,family:60};initContext(s);initFinance(s);}
export function lifeDay(s){initLife(s);let p=hero(s),l=s.life;
 financeDay(s);observeLife(s);
 if(s.day%30===0){p.fatigue=clamp(p.fatigue+Math.min(6,l.sponsors.reduce((n,c)=>n+c.obligation,0)));l.family=clamp(l.family+(s.activity==='famille'?3:-.3));if(l.partner)l.partner.bond=clamp(l.partner.bond+(s.activity==='famille'?2:-.2));l.morale=clamp(l.morale*.9+(s.activity==='famille'?85:70)*.1);s.relationships.family=l.family;}
 if(l.expecting&&s.day>=l.expecting&&!s.pending){l.children.push({...newPerson(s,'child-'+(l.children.length+1),'Enfant'),born:s.day});delete l.expecting;l.morale=clamp(l.morale+8);l.history.push({day:s.day,title:'Naissance',text:'La famille accueille un enfant.'});s.pending={type:'life',kind:'birth',major:true,title:'La famille s’agrandit',text:'Votre enfant est né. Un nouveau chapitre commence, avec du temps à partager entre vos proches et votre carrière.',choices:[['family','Consacrer du temps à ma famille','Vos liens se renforcent.'],['rest','Organiser cette nouvelle vie','Retrouver votre équilibre.']]};log(s,'Naissance','La famille accueille un enfant.');}
 if(!s.pending){let event=contextEvent(s);if(!event&&s.day>=l.nextEvent){event=lifeEvent(s);l.nextEvent=s.day+42;}if(event){s.pending=event;const delegated=delegateChoice(s,event);if(delegated){const label=event.choices.find(c=>c[0]===delegated.choice)[1],effect=event.choices.find(c=>c[0]===delegated.choice)[2];resolveLife(s,delegated.choice);l.delegationLog.unshift({day:s.day,domain:delegated.domain,title:event.title,choice:label,reason:'Consigne durable : '+delegated.choice,effect});l.delegationLog=l.delegationLog.slice(0,100);}}}

}
function lifeEvent(s){let l=s.life,p=hero(s);l.sequence=(l.sequence||0)+1;let n=l.sequence%5;
 if(n===1&&!l.partner&&p.age>=18&&s.day>=l.preferences.meetingAfter)return {type:'life',kind:'relationship',major:true,title:'Une rencontre qui compte',text:'Une personne de votre entourage souhaite vous revoir. Votre calendrier laisse une place à une relation.',choices:[['date','Prendre du temps ensemble','Une relation peut commencer.'],['rest','Rester concentré sur le basket','Votre temps reste disponible.']],default:'date'};
 if(n===2&&l.partner&&p.age>=21&&l.children.length<3&&!l.expecting&&s.day>=l.preferences.familyAfter)return {type:'life',kind:'family',major:true,title:'Un projet de famille',text:'Votre couple envisage un enfant. Ce choix durable influencera votre temps, vos dépenses et votre attachement à une ville.',choices:[['child','Fonder ou agrandir la famille','Un nouveau chapitre, avec un peu moins de temps libre.'],['rest','En reparler plus tard','Aucune pénalité de carrière.']]};
 if(n===3&&s.career.stage==='pro'&&l.fame>=18&&!l.sponsors.length&&l.preferences.exposure!=='none')return {type:'life',kind:'sponsor',major:l.preferences.exposure==='national',title:'Votre premier partenariat',text:'Deux marques proposent des engagements différents. Les montants sont des valeurs de simulation.',choices:[['local','Marque locale · liberté','Moins d’argent, peu de rendez-vous.'],...(l.preferences.exposure==='national'?[['national','Marque nationale · exposition','Plus d’argent et quelques obligations.']]:[]),['rest','Refuser pour le moment','Conserver tout votre temps.']],default:'local'};
 if(n===4&&l.fame>=25)return {type:'life',kind:'media',title:s.grade>=70?'Les médias suivent votre série':'Les médias questionnent votre rôle',text:`Votre dernière performance et votre place dans la rotation attirent des questions à ${team(s).name}.`,choices:[['team','Mettre le collectif en avant','Renforce les relations avec l’équipe.'],['ambition','Affirmer vos ambitions','Développe votre notoriété.'],['rest','Laisser l’agent répondre','Préserve votre tranquillité.']],default:'team'};
 return {type:'life',kind:'balance',title:'Une semaine pour vous',text:'Votre entourage propose un moment ensemble. Comment utiliser ce temps disponible ?',choices:[['family','Retrouver vos proches','Relations et moral en hausse.'],['work','Travailler avec votre mentor','Une séance supplémentaire, un peu de fatigue.'],['rest','Souffler','Récupération et sérénité.']],default:'family'};
}
export function resolveLife(s,choice){if(!canChange(s,{pending:true}))return false;let e=s.pending;if(e?.type!=='life'||!e.choices.some(c=>c[0]===choice))return false;let l=s.life,p=hero(s),text=e.choices.find(c=>c[0]===choice)[1];
 if(choice==='date'){l.partner={...newPerson(s,'partner-1','Partenaire'),bond:65,since:s.day};l.morale=clamp(l.morale+5);}
 if(choice==='child'){l.expecting=s.day+270;l.morale=clamp(l.morale+5);l.history.push({day:s.day,title:'Projet de famille',text:'Un enfant est attendu dans neuf mois.'});}
 if(choice==='local'||choice==='national'){let annual=Math.round((choice==='local'?4000:16000)*(1+l.fame/12)*(1+Math.min(5,s.careerLedger?.titles.filter(t=>t.eligible).length||0)*.1)*(s.league==='nba'?1.25:1));l.sponsors.push({name:choice==='local'?'Équipementier local':'Équipementier national',annual,ends:s.day+730,obligation:choice==='national'?2:1});l.fame=clamp(l.fame+(choice==='national'?4:1));}
 if(choice==='team')s.relationships.team=clamp(s.relationships.team+4);
 if(choice==='ambition')l.fame=clamp(l.fame+4);
 if(choice==='family'){l.family=clamp(l.family+6);if(l.partner)l.partner.bond=clamp(l.partner.bond+5);l.morale=clamp(l.morale+4);}
 if(choice==='work'){s.relationships.mentor=clamp(s.relationships.mentor+4);p.fatigue=clamp(p.fatigue+3);s.life.bonusTraining=true;}
 if(choice==='rest'){p.fatigue=clamp(p.fatigue-6);l.morale=clamp(l.morale+2);}
 rememberChoice(s,e,choice,text);log(s,e.title,text);s.pending=null;return true;
}
export function lifeAction(s,action){initLife(s);return financeAction(s,action);}
export const netWorth=s=>Math.round(s.money+(s.life?.investments||0)+(s.life?.property?.value||0));
